/* Sound box update: while the listener is inside the box's outer radius keeps the box's sound playing (restarting it
   on its timer) at a volume that falls off outside the unit box, placed at the nearest point of the box; outside,
   stops it. */
void update_box_emitter(Moby_0031AD00 *m) {
    float d[4];
    float r[4];
    float b[4];
    float c[4];
    Inst_0031AD00 *p = m->inst;
    float outer, inner, t;
    int vol;
    int flags;
    int idx;
    char *e;

    r[0] = m->radius;
    r[1] = m->radius;
    r[2] = m->radius;
    FastVecSub(d, camera_pos_r, m->pos);
    d[3] = 0;
    transform_vector_by_basis(b, d, m->mtx);
    transform_vector_by_basis(c, r, m->mtx);
    outer = FastVecLength(c);
    inner = FastVecLength(b);
    if (inner < outer) {
        flags = 0x10;
        if (absolute_float(b[0]) <= 1.0f && absolute_float(b[1]) <= 1.0f && absolute_float(b[2]) <= 1.0f) {
            vol = novalis_level_sound_slots[p->cls].fC;
        } else {
            if (b[0] > 1.0f) {
                b[0] = 1.0f;
            } else if (b[0] < -1.0f) {
                b[0] = -1.0f;
            }
            if (b[1] > 1.0f) {
                b[1] = 1.0f;
            } else if (b[1] < -1.0f) {
                b[1] = -1.0f;
            }
            if (b[2] > 1.0f) {
                b[2] = 1.0f;
            } else if (b[2] < -1.0f) {
                b[2] = -1.0f;
            }
            t = FastVecLength(b);
            vol = calculate_voice_distance_volume((char *)novalis_level_sound_slots + (p->cls << 5), inner, t, outer);
        }
        e = voice_pool + p->handle * 0x70;
        if (novalis_level_sound_slots[p->cls].f18) {
            flags = 0x14;
        }
        if (!(*(Moby_0031AD00 **)(e + 0x8C) == m && *(unsigned char *)(e + 0x74))) {
            if (fast_dec_timer(&p->timer)) {
                p->handle = play_voice_r(p->cls, flags, m, vol);
                if (p->tmax > 0) {
                    p->timer = (float)scale_ticks(p->tmin + random_integer_below(p->tmax - p->tmin)) * 60.0f;
                }
            } else {
                p->handle = -1;
            }
        }
        if (p->handle != -1) {
            Sound_SetPitchBend(p->handle, vol);
            transform_vector_by_basis(d, b, m->f10);
            FastVecAdd(d, d, m->pos);
            qcopy(voice_positions_r + p->handle * 0x70, d);
        }
    } else {
        idx = p->handle;
        if (idx != -1) {
            char *e2 = voice_pool + idx * 0x70;
            if (*(Moby_0031AD00 **)(e2 + 0x8C) == m && *(unsigned char *)(e2 + 0x74)) {
                Sound_StopSlot(idx);
            }
        }
        p->handle = -1;
    }
}

extern int truncate_float_to_s32(float);

/* reverb box sound update: starts or stops the sound as the listener enters or leaves the box */
void update_reverb_box_emitter(char *moby) {
    float a[4];
    float b[4];
    unsigned char *data = *(unsigned char **)(moby + 8);
    FastVecSub(a, &g_hero.motion.pos, moby + 0x40);
    a[3] = 0;
    transform_vector_by_basis(b, a, moby + 0x50);
    if (absolute_float(b[0]) <= 1.0f && absolute_float(b[1]) <= 1.0f && absolute_float(b[2]) <= 1.0f) {
        float t = (b[0] + 1.0f) * 0.5f;
        int v = truncate_float_to_s32(IntToFloat(*(int *)(data + 4)) * t);
        int w = *(int *)(data + 4);
        if (!(w < v))
            w = v;
        set_requested_state_and_mark_changes((int)moby, data[0], w, data[1], data[2]);
        data[3] = 1;
    } else if (data[3] != 0) {
        if (b[0] > 0.0f) {
            set_requested_state_and_mark_changes(0, data[0], *(int *)(data + 4), data[1], data[2]);
        } else {
            set_requested_state_and_mark_changes((int)moby, 0, 0, 0, 0);
        }
        data[3] = 0;
    }
}
